-- =========================================================================
-- SCRIPT SQL: INSERCIÓN MASIVA DE 100 RAZAS CANINAS OFICIALES FCI EN SUPABASE
-- =========================================================================

-- 1. Asegurar columnas de la norma FCI
ALTER TABLE breeds ADD COLUMN IF NOT EXISTS fci_group TEXT;
ALTER TABLE breeds ADD COLUMN IF NOT EXISTS fci_standard TEXT;
ALTER TABLE breeds ADD COLUMN IF NOT EXISTS fci_origin TEXT;

-- 2. Habilitar la política RLS de lectura pública
ALTER TABLE breeds ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir lectura publica a razas" ON breeds;
CREATE POLICY "Permitir lectura publica a razas" ON breeds FOR SELECT USING (true);

-- 3. Inserción de las 100 Razas Caninas con Estándar Oficial FCI y Métricas de Reactividad
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  energy_level = EXCLUDED.energy_level,
  prey_drive = EXCLUDED.prey_drive,
  sensitivity = EXCLUDED.sensitivity,
  arousal_threshold = EXCLUDED.arousal_threshold,
  fci_group = EXCLUDED.fci_group,
  fci_standard = EXCLUDED.fci_standard,
  fci_origin = EXCLUDED.fci_origin,
  image_url = EXCLUDED.image_url;
